def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    remaining = 100 - n

    # Fast path: scan aggregates in one pass.
    opp_d = 0
    opp_c = 0
    my_d = 0
    last_opp = history[-1][1]
    for me, op in history:
        if op == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if me == 'D':
            my_d += 1

    # Endgame: squeeze the last few rounds.
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        # If opponent likely still cooperating, defect to grab DC=5.
        recent = history[-4:] if n >= 4 else history
        rd = 0
        for me, op in recent:
            if op == 'D':
                rd += 1
        if rd == 0:
            return 'D' if remaining <= 2 else ('D' if rng.random() < 0.7 else 'C')
        if rd >= 2:
            return 'D'
        return 'C'

    # Heavy defector: retaliate hard.
    if n >= 8 and opp_c == 0:
        return 'D'
    if n >= 15 and opp_d * 4 >= n * 3:
        return 'D'

    # Look at recent opponent behavior.
    win = n if n < 6 else 6
    recent_d = 0
    i = n - win
    while i < n:
        if history[i][1] == 'D':
            recent_d += 1
        i += 1

    # Recent heavy defection: punish, with rare probes.
    if recent_d >= 4:
        return 'D' if rng.random() < 0.92 else 'C'
    if recent_d == 3:
        return 'D' if rng.random() < 0.8 else 'C'

    # Last opponent defected.
    if last_opp == 'D':
        # If we're likely in a mutual-defect spiral, try to break it occasionally.
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
            if rng.random() < 0.35:
                return 'C'
        # If opponent has rarely defected overall, forgive more.
        if n >= 10 and opp_d * 5 <= n:
            return 'C' if rng.random() < 0.45 else 'D'
        # If we ourselves have been defecting a lot, we likely provoked it.
        if n >= 6 and my_d * 2 >= n:
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D' if rng.random() < 0.8 else 'C'

    # Opponent cooperated last round.
    # If we defected last round and opponent still cooperated, don't over-exploit
    # an already-tolerant cooperator too aggressively.
    if n >= 1 and history[-1][0] == 'D':
        if opp_d * 5 <= n:
            # Opponent is very forgiving: mostly return to cooperation.
            if n >= 10 and rng.random() < 0.25 and remaining > 5:
                return 'D'
            return 'C'
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Opponent has been consistently cooperative: cooperate, but occasionally
    # test for exploitability without triggering permanent retaliation.
    if opp_d == 0:
        if n >= 12 and rng.random() < 0.08 and remaining > 4:
            return 'D'
        return 'C'

    # Mostly cooperative opponent.
    if opp_d * 6 <= n:
        if recent_d == 0:
            if n >= 15 and rng.random() < 0.06 and remaining > 4:
                return 'D'
            return 'C'
        # One recent defection in an otherwise clean streak: forgive.
        return 'C'

    # Moderately cooperative opponent.
    if opp_d * 3 <= n:
        if recent_d == 0:
            return 'C'
        if recent_d == 1:
            return 'C' if rng.random() < 0.6 else 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    # Mixed/unknown: cautious tit-for-tat.
    if recent_d <= 1:
        return 'C'
    if recent_d == 2:
        return 'D' if rng.random() < 0.55 else 'C'
    return 'D'
